#include <stdio.h>
#ifndef SENSOR_FAST
#define SENSOR_FAST 0
#endif
#if SENSOR_FAST
static const int gain = 2;
#else
static const int gain = 1;
#endif
int main(void) {
    int x;
    if (scanf("%d", &x) != 1) return 1;
    printf("%d\n", x * gain);
    return 0;
}
